INSERT INTO languages (code, name, native_name, is_default, enabled, rtl, sort) SELECT 'km', 'Khmer', 'ខ្មែរ', 0, 0, 0, (SELECT COALESCE(MAX(sort), 0) + 1 FROM languages) WHERE NOT EXISTS (SELECT 1 FROM languages WHERE code = 'km') AND (EXISTS (SELECT 1 FROM people WHERE trim(COALESCE(name_km, '')) != '') OR EXISTS (SELECT 1 FROM campaigns WHERE trim(COALESCE(title_km, '')) != '' OR trim(COALESCE(blurb_km, '')) != '') OR EXISTS (SELECT 1 FROM forms WHERE trim(COALESCE(title_km, '')) != '' OR trim(COALESCE(intro_km, '')) != ''));--> statement-breakpoint
INSERT INTO translations (tenant_id, entity_type, entity_id, field, lang, value) SELECT tenant_id, 'person', id, 'name', 'km', name_km FROM people WHERE name_km IS NOT NULL AND trim(name_km) != '' AND EXISTS (SELECT 1 FROM languages WHERE code = 'km') ON CONFLICT DO NOTHING;--> statement-breakpoint
